# coding: utf-8
CSS=r''':root{color-scheme:dark;--bg:#101316;--card:#171b20;--line:#343c46;--text:#eef2f4;--muted:#9da8b3;--accent:#438b5c;--warn:#e3b55a;--danger:#e47f7f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}.shell{max-width:1500px;margin:auto;padding:18px}.head,.section-title,.footer{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.head h1{margin:0}.sub,.hint{color:var(--muted);font-size:12px}.back,.pdf{color:inherit;font-weight:800}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:16px 0}.metric,.card,.note{border:1px solid var(--line);border-radius:13px;background:var(--card);padding:12px}.metric span{display:block;color:var(--muted);font-size:12px}.metric strong{font-size:20px}.card{margin-bottom:14px}.row{display:grid;grid-template-columns:34px 105px minmax(180px,1.4fr) minmax(120px,.8fr) 125px 155px 100px;gap:9px;align-items:center;padding:10px 6px;border-top:1px solid var(--line);font-size:13px}.row:first-child{border-top:0}.amount{font-weight:850;text-align:right}.gross{color:var(--muted);font-size:11px;text-decoration:line-through}.status{font-size:11px;font-weight:850}.status.sepa_submitted{color:#9cc7ff}.status.paid,.status.approved{color:#82d49d}.status.pending{color:var(--warn)}.status.blocked{color:var(--danger)}.status.reduced{color:#9cc7ff}select,button{background:#252c34;color:inherit;border:1px solid #485461;border-radius:9px;padding:8px 10px}.footer{position:sticky;bottom:0;background:#17231c;border:1px solid #496451;border-radius:13px;padding:12px}.footer button{background:var(--accent);font-weight:850}.empty{padding:20px;text-align:center;color:var(--muted)}.unknown .row{grid-template-columns:105px minmax(180px,1.4fr) minmax(120px,.8fr) 115px 190px}.note{margin-bottom:14px;color:var(--muted)}.approval-note{background:#171f18;border-color:#425747}.approval-note.warn{background:#241d12;border-color:#66512e}.approval-note strong{color:var(--text)}@media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.row,.unknown .row{grid-template-columns:1fr 1fr}.amount{text-align:left}.footer{position:static}}@media(max-width:520px){.metrics,.row,.unknown .row{grid-template-columns:1fr}}'''

def payments_page():
 return fr'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KRISTINE · Bezahlung</title><style>{CSS}</style></head><body><main class="shell"><div class="head"><div><h1>Bezahlung</h1><div class="sub">Bezahl-OP · nur freigegebene Überweisungen dürfen in SEPA.</div></div><a class="back" href="/">← The Brain</a></div><div class="metrics"><div class="metric"><span>Bezahl-OP</span><strong id="cnt">–</strong></div><div class="metric"><span>OP zahlbar</span><strong id="tot">–</strong></div><div class="metric"><span>Freigaben</span><strong id="approvals">–</strong></div><div class="metric"><span>Ausgewählt</span><strong id="sel">0</strong></div><div class="metric"><span>Zahlungssumme</span><strong id="sum">0,00 €</strong></div></div><div id="approvalInfo" class="note approval-note">Freigaben aus KRISTINE werden geprüft …</div><section class="card"><div class="section-title"><h2>Offene Überweisungen</h2><span class="hint">Nur freigegebene Rechnungen sind auswählbar. Kürzungen werden als tatsächlicher Überweisungsbetrag verwendet.</span></div><div id="rows"><div class="empty">Wird geladen …</div></div></section><section class="card unknown"><div class="section-title"><h2>Zahlungsart noch klären</h2><span class="hint">Einzug/Revolut/Bar verschwinden danach aus dem Bezahl-OP.</span></div><div id="unknown"><div class="empty">Wird geladen …</div></div></section><div class="footer"><div><span id="fc">0</span> Rechnung(en) · <strong id="fs">0,00 €</strong></div><button id="go" disabled>Zahlung vorbereiten</button></div></main><script>
(()=>{{const box=document.getElementById('rows'),ub=document.getElementById('unknown'),go=document.getElementById('go'),approvalInfo=document.getElementById('approvalInfo');let rows=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c])),money=(n,c='EUR')=>new Intl.NumberFormat('de-AT',{{style:'currency',currency:c||'EUR'}}).format(Number(n||0)),date=s=>{{const m=String(s||'').match(/^(\d{{4}})-(\d{{2}})-(\d{{2}})/);return m?m[3]+'.'+m[2]+'.'+m[1]:(s||'–')}},opts=v=>[['unknown','– auswählen –'],['transfer','Überweisung / SEPA'],['direct_debit','Einzug / Lastschrift'],['revolut','Revolut / Kreditkarte'],['cash','Bar / Kassa']].map(([k,t])=>`<option value="${{k}}" ${{k===v?'selected':''}}>${{t}}</option>`).join(''),pdf=r=>r.path?`<a class="pdf" href="/pdf?path=${{encodeURIComponent(r.path)}}" target="_blank">PDF</a>`:'–',approvalLabel=r=>{{if(r.approvalStatus==='approved')return '<span class="status approved">✓ freigegeben</span>';if(r.approvalStatus==='reduced')return `<span class="status reduced">✂ gekürzt · ${{esc(money(r.approvalDeduction,r.currency))}}</span>${{r.approvalReason?`<div class="sub">${{esc(r.approvalReason)}}</div>`:''}}`;if(r.approvalStatus==='blocked')return `<span class="status blocked">⛔ gesperrt</span>${{r.approvalReason?`<div class="sub">${{esc(r.approvalReason)}}</div>`:''}}`;if(r.approvalStatus==='pending')return '<span class="status pending">⏳ Freigabe offen</span>';return '<span class="status">Altbestand</span>'}},payable=r=>r.paymentStatus!=='sepa_submitted'&&['approved','reduced','not_required'].includes(r.approvalStatus)&&Number(r.paymentAmount??r.amount)>0;function selected(){{const a=[...box.querySelectorAll('[data-s]:checked')].map(e=>{{const [s,id]=e.dataset.s.split('|');return rows.find(r=>r.source===s&&r.id===id)}}).filter(Boolean),t=a.reduce((x,r)=>x+Number(r.paymentAmount??r.amount??0),0);sel.textContent=fc.textContent=a.length;sum.textContent=fs.textContent=money(t);go.disabled=!a.length;return a}}function render(r,u,d){{rows=r;cnt.textContent=d.count;tot.textContent=money(d.total);approvals.textContent=`${{Number(d.approvalPendingCount||0)}} offen · ${{Number(d.approvalApprovedCount||0)}} frei`;approvalInfo.classList.toggle('warn',Boolean(d.approvalSyncError||d.approvalPendingCount||d.approvalBlockedCount));approvalInfo.innerHTML=d.approvalSyncError?`<strong>Freigabe-Sync nicht erreichbar.</strong> KRISTINE-Rechnungen bleiben aus Sicherheitsgründen für SEPA gesperrt. · ${{esc(d.approvalSyncError)}}`:`<strong>Freigaben aus Brain:</strong> ${{Number(d.approvalPendingCount||0)}} warten auf Entscheidung · ${{Number(d.approvalApprovedCount||0)}} freigegeben/gekürzt · ${{Number(d.approvalBlockedCount||0)}} gesperrt.`;box.innerHTML=r.length?r.map(x=>{{const pay=Number(x.paymentAmount??x.amount??0),reduced=x.approvalStatus==='reduced'&&Math.abs(pay-Number(x.amount||0))>.004,disabled=!payable(x);return `<div class="row"><input type="checkbox" data-s="${{esc(x.source)}}|${{esc(x.id)}}" ${{disabled?'disabled':''}}><div>${{esc(date(x.dueDate))}}</div><div><strong>${{esc(x.supplier)}}</strong><div class="sub">${{esc(x.paymentId||'')}}</div></div><div>${{esc(x.invoiceNumber||'–')}}</div><div class="amount">${{esc(money(pay,x.currency))}}${{reduced?`<div class="gross">${{esc(money(x.amount,x.currency))}}</div>`:''}}</div><div>${{x.paymentStatus==='sepa_submitted'?'<span class="status sepa_submitted">SEPA übergeben</span>':approvalLabel(x)}}</div><div>${{pdf(x)}}</div></div>`}}).join(''):'<div class="empty">Keine offenen Überweisungen.</div>';ub.innerHTML=u.length?u.map(x=>`<div class="row"><div>${{esc(date(x.dueDate))}}</div><div><strong>${{esc(x.supplier)}}</strong><div class="sub">${{x.source==='KRISTINE'?approvalLabel(x):''}}</div></div><div>${{esc(x.invoiceNumber||'–')}}</div><div class="amount">${{esc(money(x.amount,x.currency))}}</div><select data-m="${{esc(x.source)}}|${{esc(x.id)}}">${{opts(x.paymentMethod)}}</select></div>`).join(''):'<div class="empty">Keine ungeklärten Zahlungsarten.</div>';box.querySelectorAll('[data-s]').forEach(e=>e.onchange=selected);ub.querySelectorAll('[data-m]').forEach(e=>e.onchange=async()=>{{const [source,id]=e.dataset.m.split('|'),q=await fetch('/incoming/payment-meta',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{source,id,paymentMethod:e.value}})}}),j=await q.json();if(!q.ok||!j.ok)alert(j.error||'Fehler');else load()}});selected()}}async function load(){{const q=await fetch('/incoming/payment-open-items',{{cache:'no-store'}}),d=await q.json();if(!q.ok||!d.ok)throw Error(d.error||'Bezahl-OP konnte nicht geladen werden');render(d.items||[],d.unclassified||[],d)}}go.onclick=async()=>{{const a=selected();if(!a.length||!confirm(`${{a.length}} freigegebene Rechnung(en) für SEPA vorbereiten?\n\nZahlungssumme: ${{money(a.reduce((s,x)=>s+Number(x.paymentAmount??x.amount??0),0))}}\n\nBezahlt wird erst nach Bankfreigabe und späterem CAMT-Abgleich.`))return;const q=await fetch('/incoming/payment-batch/prepare',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{items:a.map(x=>({{source:x.source,id:x.id}}))}})}}),d=await q.json();if(!q.ok||!d.ok)return alert(d.error||'Fehler');alert(`${{d.count}} Rechnung(en) · ${{money(d.total)}}\nStatus: SEPA übergeben\n\nKürzungsgründe sind als Überweisungstext vorbereitet.`);load()}};load().catch(e=>box.innerHTML=`<div class="empty">${{esc(e.message)}}</div>`)}})();
</script></body></html>'''

def revolut_page():
 return fr'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KRISTINE · Revolut</title><style>{CSS}</style></head><body><main class="shell"><div class="head"><div><h1>Revolut</h1><div class="sub">Eigener Abgleich für Karten-/Onlinebelege.</div></div><a class="back" href="/">← Erfassung</a></div><div class="note">Jede Revolut-Bewegung wird gegen Rechnung/Beleg abgeglichen. Offene Fälle bleiben sichtbar: Beleg fehlt, Zuordnung offen oder privat. Bank → Revolut ist nur Umbuchung.</div><div class="metrics"><div class="metric"><span>Belege</span><strong id="cnt">–</strong></div><div class="metric"><span>Offen</span><strong id="open">–</strong></div><div class="metric"><span>Offener Betrag</span><strong id="tot">–</strong></div><div class="metric"><span>Privat</span><strong>folgt</strong></div></div><section class="card"><div class="section-title"><h2>Belege / Rechnungen</h2><span class="hint">Transaktionsimport + Mail-Belegsuche folgt als nächster Schritt.</span></div><div id="rows"><div class="empty">Wird geladen …</div></div></section></main><script>
(()=>{{const b=document.getElementById('rows'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c])),money=n=>new Intl.NumberFormat('de-AT',{{style:'currency',currency:'EUR'}}).format(Number(n||0));fetch('/incoming/revolut/items',{{cache:'no-store'}}).then(r=>r.json().then(d=>[r,d])).then(([r,d])=>{{if(!r.ok||!d.ok)throw Error(d.error||'Fehler');cnt.textContent=d.count;open.textContent=d.openCount;tot.textContent=money(d.openTotal);b.innerHTML=(d.items||[]).length?(d.items||[]).map(x=>`<div class="row" style="grid-template-columns:105px minmax(180px,1.5fr) minmax(120px,.8fr) 115px 135px 100px"><div>${{esc(x.invoiceDate||'–')}}</div><div><strong>${{esc(x.supplier)}}</strong></div><div>${{esc(x.invoiceNumber||'–')}}</div><div class="amount">${{money(x.amount)}}</div><div class="status ${{esc(x.paymentStatus)}}">${{x.paymentStatus==='paid'?'bezahlt':'Abgleich offen'}}</div><div>${{x.path?`<a class="pdf" href="/pdf?path=${{encodeURIComponent(x.path)}}" target="_blank">PDF</a>`:'Beleg fehlt'}}</div></div>`).join(''):'<div class="empty">Noch keine Revolut-Belege markiert.</div>'}}).catch(e=>b.innerHTML=`<div class="empty">${{esc(e.message)}}</div>`)}})();
</script></body></html>'''
